UPDATE sr_knowledge_mastery
        SET first_learned_at = COALESCE(first_learned_at, UTC_TIMESTAMP(3))
        WHERE account_id = #{accountId} AND knowledge_card_id = #{cardId}

UPDATE sr_knowledge_mastery
        SET evidence_count = #{evidenceCount},
            last_recall_rating = #{lastRecallRating},
            last_evidence_at = #{lastEvidenceAt},
            system_suggested_level = #{systemSuggestedLevel}
        WHERE id = #{id}
